<?php
declare(strict_types=1);
final class FlowService {
 public function __construct(private PDO $db,private LeadService $leads){}
 public function validate(array $g):array{$errors=[];$nodes=$g['nodes']??[];$ids=array_column($nodes,'id');if(count(array_filter($nodes,fn($n)=>($n['type']??'')==='start'))!==1)$errors[]='O fluxo deve ter exatamente um início.';foreach($nodes as $n){if(empty($n['id'])||empty($n['type']))$errors[]='Todo bloco precisa de ID e tipo.';foreach(['message','question'] as $t)if(($n['type']??'')===$t&&empty($n['config']['text']))$errors[]="Bloco {$n['id']} exige texto.";$next=$n['next']??null;if($next&&!in_array($next,$ids,true))$errors[]="Saída do bloco {$n['id']} está desconectada.";if(!in_array($n['type']??'', ['end','human'],true)&&!$next&&($n['type']??'')!=='condition')$errors[]="Bloco {$n['id']} não possui saída.";}return array_values(array_unique($errors));}
 public function save(?string $flowId,string $name,array $graph,array $u):array{if(!in_array($u['role'],['admin','manager'],true))throw new AuthorizationException('Editor restrito a gestor e administrador.');$errors=$this->validate($graph);$this->db->beginTransaction();try{if(!$flowId){$flowId=uid();$this->db->prepare('INSERT INTO automation_flows(id,name,created_by) VALUES(?,?,?)')->execute([$flowId,$name,$u['id']]);}else $this->db->prepare('UPDATE automation_flows SET name=?,status=IF(status=\'published\',status,\'draft\') WHERE id=?')->execute([$name,$flowId]);$q=$this->db->prepare('SELECT COALESCE(MAX(version_number),0)+1 FROM flow_versions WHERE flow_id=?');$q->execute([$flowId]);$version=$q->fetchColumn();$vid=uid();$this->db->prepare('INSERT INTO flow_versions(id,flow_id,version_number,graph,validation_errors,created_by) VALUES(?,?,?,?,?,?)')->execute([$vid,$flowId,$version,json_encode($graph),$errors?json_encode($errors):null,$u['id']]);$this->db->prepare('UPDATE automation_flows SET draft_version_id=? WHERE id=?')->execute([$vid,$flowId]);$this->db->commit();return ['id'=>$flowId,'version_id'=>$vid,'errors'=>$errors];}catch(Throwable $e){$this->db->rollBack();throw $e;}}
 public function publish(string $id,array $u):void{if(!in_array($u['role'],['admin','manager'],true))throw new AuthorizationException('Publicação não autorizada.');$q=$this->db->prepare('SELECT draft_version_id FROM automation_flows WHERE id=?');$q->execute([$id]);$vid=$q->fetchColumn();if(!$vid)throw new RuntimeException('Fluxo sem rascunho.');$q=$this->db->prepare('SELECT validation_errors FROM flow_versions WHERE id=?');$q->execute([$vid]);if($q->fetchColumn())throw new DomainException('Corrija os erros antes de publicar.');$this->db->prepare("UPDATE automation_flows SET published_version_id=?,status='published' WHERE id=?")->execute([$vid,$id]);}
 public function message(string $flowId,string $conversationId,string $body,bool $integrated,array $u):array{$q=$this->db->prepare('SELECT f.draft_version_id,v.graph FROM automation_flows f JOIN flow_versions v ON v.id=f.draft_version_id WHERE f.id=?');$q->execute([$flowId]);$row=$q->fetch();if(!$row)throw new RuntimeException('Fluxo não encontrado.');$graph=json_decode($row['graph'],true);$nodes=[];foreach($graph['nodes'] as $n)$nodes[$n['id']]=$n;$q=$this->db->prepare("SELECT * FROM conversations WHERE provider='simulator' AND external_id=?");$q->execute([$conversationId]);$c=$q->fetch();if(!$c){$cid=uid();$start=current(array_filter($nodes,fn($n)=>$n['type']==='start'));$state=['data'=>[]];$this->db->prepare("INSERT INTO conversations(id,provider,external_id,flow_version_id,current_node_id,state,status) VALUES(?,'simulator',?,?,?,?, 'active')")->execute([$cid,$conversationId,$row['draft_version_id'],$start['next'],json_encode($state)]);$c=['id'=>$cid,'current_node_id'=>$start['next'],'state'=>json_encode($state),'automation_paused'=>0];}if($c['automation_paused'])return ['replies'=>[],'path'=>[],'data'=>json_decode($c['state'],true)['data']??[],'human'=>true];$mid='sim-in-'.hash('sha256',$conversationId.'|'.$body.'|'.microtime(true));$this->db->prepare("INSERT INTO conversation_messages(id,conversation_id,provider,external_message_id,direction,body,status) VALUES(?,?,?,?,'in',?,'simulated')")->execute([uid(),$c['id'],'simulator',$mid,$body]);$state=json_decode($c['state'],true)?:['data'=>[]];$nodeId=$c['current_node_id'];$replies=[];$path=[];$guard=0;$human=false;if(!empty($state['waiting_field'])){$state['data'][$state['waiting_field']]=$body;unset($state['waiting_field']);$nodeId=$nodes[$nodeId]['next']??$nodeId;}while($nodeId&&isset($nodes[$nodeId])&&$guard++<50){$n=$nodes[$nodeId];$path[]=$nodeId;$type=$n['type'];if($type==='message'){$replies[]=$n['config']['text'];$nodeId=$n['next']??null;continue;}if($type==='question'){$replies[]=$n['config']['text'];$state['waiting_field']=$n['config']['field'];break;}if($type==='save'){$state['data'][$n['config']['field']]=$body;$nodeId=$n['next']??null;continue;}if($type==='condition'){$value=strtolower((string)($state['data'][$n['config']['field']]??$body));$nodeId=str_contains($value,strtolower($n['config']['contains']))?($n['config']['yes']??null):($n['config']['no']??null);continue;}if($type==='create_lead'){if($integrated&&!empty($state['data']['name'])){$source=$this->db->query("SELECT id FROM lead_sources WHERE code='whatsapp' LIMIT 1")->fetchColumn();$lead=$this->leads->create(['name'=>$state['data']['name'],'phone'=>$state['data']['phone']??('teste-'.substr($conversationId,-8)),'source_id'=>$source,'external_id'=>'sim-'.$conversationId,'interest_type'=>$n['config']['interest_type']??$state['data']['interest_type']??'purchase','region'=>$state['data']['region']??null,'max_value'=>$state['data']['max_value']??null,'property_interest'=>'TESTE LOCAL DO SIMULADOR'],$u['id']);$state['lead_id']=$lead['id'];$this->db->prepare('UPDATE conversations SET contact_id=?,opportunity_id=?,phone=? WHERE id=?')->execute([$lead['contact_id'],$lead['id'],$state['data']['phone']??null,$c['id']]);}$nodeId=$n['next']??null;continue;}if($type==='human'){$human=true;$nodeId=null;break;}if($type==='end'){$nodeId=null;break;}$nodeId=$n['next']??null;}if($guard>=50)throw new DomainException('Execução interrompida: possível ciclo infinito.');$status=!empty($state['waiting_field'])?'waiting':($human?'human':($nodeId?'active':'closed'));$this->db->prepare('UPDATE conversations SET current_node_id=?,state=?,status=?,automation_paused=? WHERE id=?')->execute([$nodeId,json_encode($state),$status,$human?1:0,$c['id']]);foreach($replies as $i=>$text)$this->db->prepare("INSERT INTO conversation_messages(id,conversation_id,provider,external_message_id,direction,body,block_id,status) VALUES(?,?,? ,?,'out',?,?, 'simulated')")->execute([uid(),$c['id'],'simulator','sim-out-'.uid(),$text,$path[$i]??null]);return ['replies'=>$replies,'path'=>$path,'data'=>$state['data'],'lead_id'=>$state['lead_id']??null,'status'=>$status];}
}
